if(!window.DecompressionStream&&window.pako){window.DecompressionStream=class{constructor(format){if(format!=="gzip"&&format!=="deflate")throw new TypeError("Unsupported format");const chunks=[];return new TransformStream({transform(chunk){chunks.push(chunk instanceof Uint8Array?chunk:new Uint8Array(chunk))},flush(controller){const size=chunks.reduce((sum,chunk)=>sum+chunk.length,0),input=new Uint8Array(size);let offset=0;for(const chunk of chunks){input.set(chunk,offset);offset+=chunk.length}controller.enqueue(format==="gzip"?window.pako.ungzip(input):window.pako.inflate(input))}})}}}

(()=>{const storageKey="wind-question-seen-v4";const normalize=value=>String(value??"").normalize("NFKC").toLowerCase().replace(/[“”'"`]/g,"").replace(/\s+/g," ").trim();const fingerprint=q=>[q.subject,q.stage,q.type,normalize(q.prompt),normalize(q.answer)].join("|");const shuffle=list=>{const copy=[...list];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy};const valid=q=>{if(!q||!normalize(q.prompt)||!normalize(q.answer)||!normalize(q.explanation))return false;if(q.type==="input")return true;if(q.type!=="choice"||!Array.isArray(q.options)||q.options.length<2)return false;const options=q.options.map(normalize);return new Set(options).size===options.length&&options.filter(option=>option===normalize(q.answer)).length===1};const variants=q=>{if(!valid(q))return[];const list=[q];if(q.type==="choice"&&String(q.answer).length<=14)list.push({...q,id:`v-${Date.now()}-${Math.random()}`,type:"input",prompt:`请填写正确答案：${String(q.prompt).replace(/[？?]\s*$/,"")}`,options:undefined});return list};const load=()=>{try{return JSON.parse(localStorage.getItem(storageKey)||"{}")||{}}catch{return{}}};const save=value=>{try{localStorage.setItem(storageKey,JSON.stringify(value))}catch{}};const wrap=engine=>{if(!engine||engine.__qualityV4||typeof engine.generate!=="function")return engine;const original=engine.generate.bind(engine);engine.generate=config=>{const requested=Math.max(1,Math.min(50,Number(config?.count)||10));const bucket=[config?.subject||"math",config?.stage||"primary",config?.system||"integrated",Number(config?.difficulty)||2].join("|");const history=load();let seen=new Set(Array.isArray(history[bucket])?history[bucket]:[]);const session=new Set();const result=[];let attempts=0;const collect=allowSeen=>{while(result.length<requested&&attempts<requested*500){attempts++;const raw=original({...config,count:1})?.[0];if(!raw)continue;for(const item of shuffle(variants(raw))){const key=fingerprint(item);if(session.has(key)||(!allowSeen&&seen.has(key)))continue;session.add(key);result.push(item);if(result.length>=requested)break}}};collect(false);if(!result.length&&seen.size){seen=new Set();attempts=0;collect(true)}history[bucket]=[...seen,...result.map(fingerprint)].slice(-4000);save(history);return result};engine.questionFingerprint=fingerprint;engine.__qualityV4=true;return engine};let current=window.WIND_QUESTIONS;Object.defineProperty(window,"WIND_QUESTIONS",{configurable:true,get(){return current},set(value){current=wrap(value)}});if(current)current=wrap(current)})();

